package com.slayeraio;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SlayerAIOPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SlayerAIOPlugin.class);
		RuneLite.main(args);
	}
}

package com.slayeraio;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class SlayerMonstersTest
{
	@Test
	public void matchesExactCategoryCaseInsensitively()
	{
		assertEquals("Aberrant spectres", SlayerMonsters.matchCategory("ABERRANT SPECTRES"));
	}

	@Test
	public void matchesWithSurroundingWhitespace()
	{
		assertEquals("Kurasks", SlayerMonsters.matchCategory("  Kurasks  "));
	}

	@Test
	public void returnsNullForUnknownName()
	{
		assertNull(SlayerMonsters.matchCategory("Not A Real Task"));
	}

	@Test
	public void returnsNullForNullInput()
	{
		assertNull(SlayerMonsters.matchCategory(null));
	}
}

package com.slayeraio;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Per-monster combat-defence data (stab/slash/crush/magic/standard-ranged defence), any
 * elemental spell weakness, and any item or mechanic required to damage/survive them --
 * sourced directly from each monster's {{Infobox Monster}} template (plus a handful of
 * wiki-sourced requirement sentences pulled from surrounding prose) in the local
 * osrs-wiki-data-master copy -- not hand-recalled. Used to recommend a preferred combat
 * style for the active Slayer task.
 *
 * Coverage gaps: a small number of monsters have no entry -- mostly high-end/quest-tied
 * bosses with non-standard infoboxes, or generic species-overview pages with no dedicated
 * combat infobox at all (e.g. Monkey, Troll, Icy cave crawler). Callers must handle a null
 * lookup from {@link #MONSTERS}.
 *
 * A monster's raw defence numbers can be misleading on their own -- e.g. Kurask/Turoth show
 * an unremarkable stab defence, but are actually immune to everything except leaf-bladed
 * weapons/broad ammo/Magic Dart. That's exactly the kind of case {@link Profile#requirement}
 * exists to surface; always show it alongside the computed style recommendation, not instead.
 */
public final class SlayerCombatData
{
	public enum MeleeStyle { STAB, SLASH, CRUSH }

	public enum RangedStyle { RANGE, MAGE }

	public static final class Profile
	{
		public final Integer dStab;
		public final Integer dSlash;
		public final Integer dCrush;
		public final Integer dMagic;
		public final Integer dRanged;
		public final String attackStyle;
		public final String requirement;
		/** e.g. "Air", "Water" -- the spell element that gets a damage bonus against this monster. Null if none. */
		public final String elementalWeaknessType;
		/** Damage bonus percentage for casting {@link #elementalWeaknessType} spells, e.g. 50 for +50%. Null if none. */
		public final Integer elementalWeaknessPercent;
		/** True if the Dwarf multicannon cannot damage this monster. Null if not specified on the wiki. */
		public final Boolean immuneCannon;
		/** Name of an item this monster (and only this monster, per the wiki) drops. Null if none. */
		public final String uniqueDropName;
		/** Drop rarity text for {@link #uniqueDropName}, e.g. "1/512", verbatim from the wiki. Null if none. */
		public final String uniqueDropRate;

		Profile(Integer dStab, Integer dSlash, Integer dCrush, Integer dMagic, Integer dRanged, String attackStyle, String requirement, String elementalWeaknessType, Integer elementalWeaknessPercent, Boolean immuneCannon, String uniqueDropName, String uniqueDropRate)
		{
			this.dStab = dStab;
			this.dSlash = dSlash;
			this.dCrush = dCrush;
			this.dMagic = dMagic;
			this.dRanged = dRanged;
			this.attackStyle = attackStyle;
			this.requirement = requirement;
			this.elementalWeaknessType = elementalWeaknessType;
			this.elementalWeaknessPercent = elementalWeaknessPercent;
			this.immuneCannon = immuneCannon;
			this.uniqueDropName = uniqueDropName;
			this.uniqueDropRate = uniqueDropRate;
		}

		/** Melee style(s) with the lowest defence -- i.e. cheapest to exploit with melee. Empty if no melee defence data. */
		public List<MeleeStyle> bestMeleeStyles()
		{
			Map<MeleeStyle, Integer> byStyle = new HashMap<>();
			if (dStab != null) byStyle.put(MeleeStyle.STAB, dStab);
			if (dSlash != null) byStyle.put(MeleeStyle.SLASH, dSlash);
			if (dCrush != null) byStyle.put(MeleeStyle.CRUSH, dCrush);
			if (byStyle.isEmpty()) return Collections.emptyList();
			int min = Collections.min(byStyle.values());
			List<MeleeStyle> best = new ArrayList<>();
			for (MeleeStyle s : MeleeStyle.values()) if (min == byStyle.getOrDefault(s, Integer.MAX_VALUE)) best.add(s);
			return best;
		}

		/** Whichever of Range or Mage has the lower defence value, i.e. cheaper to exploit. Ties favour Range. Null if neither is known. */
		public RangedStyle bestRangedStyle()
		{
			if (dRanged == null && dMagic == null) return null;
			if (dMagic == null) return RangedStyle.RANGE;
			if (dRanged == null) return RangedStyle.MAGE;
			return dRanged <= dMagic ? RangedStyle.RANGE : RangedStyle.MAGE;
		}
	}

	public static final Map<String, Profile> MONSTERS = buildMonsters();

	private SlayerCombatData()
	{
	}

	private static Map<String, Profile> buildMonsters()
	{
		Map<String, Profile> m = new HashMap<>();
		put1(m);
		put2(m);
		put3(m);
		put4(m);
		put5(m);
		put6(m);
		put7(m);
		put8(m);
		return Collections.unmodifiableMap(m);
	}

	private static void put(Map<String, Profile> m, String name, Integer dStab, Integer dSlash, Integer dCrush, Integer dMagic, Integer dRanged, String attackStyle, String requirement, String elementalWeaknessType, Integer elementalWeaknessPercent, Boolean immuneCannon, String uniqueDropName, String uniqueDropRate)
	{
		m.put(name, new Profile(dStab, dSlash, dCrush, dMagic, dRanged, attackStyle, requirement, elementalWeaknessType, elementalWeaknessPercent, immuneCannon, uniqueDropName, uniqueDropRate));
	}

