package com.slayeraio;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "SlayerAIO"
)
public class SlayerAIOPlugin extends Plugin
{
	private static final Set<String> SLAYER_MASTERS = Set.of(
		"Turael", "Spria", "Mazchna", "Vannaka", "Chaeldar",
		"Nieve", "Steve", "Duradel", "Krystilia", "Konar quo Maten"
	);

	@Inject
	private Client client;

	@Inject
	private SlayerAIOConfig config;

	@Inject
	private ShortestPathIntegration shortestPath;

	@Inject
	private Notifier notifier;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SlayerTaskOverlay taskOverlay;

	@Inject
	private SlayerNpcHighlightOverlay npcHighlightOverlay;

	private String currentTask;
	private int currentTaskAmount;
	private int currentTaskInitialAmount;
	private String currentTaskLocation;

	private String lastMasterTalkedTo;
	private String assignedByMaster;

	// NPCs currently in the scene that count toward currentTask, and the subset of those that
	// are superior spawns -- maintained via spawn/despawn events, not a per-frame scene scan.
	private final Set<NPC> taskNpcs = new HashSet<>();
	private final Set<NPC> superiorNpcs = new HashSet<>();

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(taskOverlay);
		overlayManager.add(npcHighlightOverlay);
		clientThread.invokeLater(this::updateTaskFromVarps);
		log.debug("SlayerAIO started!");
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(taskOverlay);
		overlayManager.remove(npcHighlightOverlay);
		shortestPath.clearPath();
		taskNpcs.clear();
		superiorNpcs.clear();
		log.debug("SlayerAIO stopped!");
	}

	String getCurrentTask()
	{
		return currentTask;
	}

	Set<NPC> getTaskNpcs()
	{
		return taskNpcs;
	}

	Set<NPC> getSuperiorNpcs()
	{
		return superiorNpcs;
	}

	int getCurrentTaskAmount()
	{
		return currentTaskAmount;
	}

	int getCurrentTaskInitialAmount()
	{
		return currentTaskInitialAmount;
	}

	String getCurrentTaskLocation()
	{
		return currentTaskLocation;
	}

	String getAssignedByMaster()
	{
		return assignedByMaster;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (gameStateChanged.getGameState() == GameState.LOGGED_IN)
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "SlayerAIO says " + config.greeting(), null);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		if (event.getMessage().contains(SlayerSuperiors.SPAWN_MESSAGE))
		{
			notifier.notify(config.superiorNotification(), "A superior Slayer monster has appeared!");
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varpId = event.getVarpId();
		int varbitId = event.getVarbitId();
		if (varpId == VarPlayerID.SLAYER_COUNT
			|| varpId == VarPlayerID.SLAYER_AREA
			|| varpId == VarPlayerID.SLAYER_TARGET
			|| varbitId == VarbitID.SLAYER_TARGET_BOSSID
			|| varpId == VarPlayerID.SLAYER_COUNT_ORIGINAL)
		{
			clientThread.invokeLater(this::updateTaskFromVarps);
		}
	}

	/**
	 * Mirrors RuneLite's own bundled Slayer plugin's updateTask() (SlayerPlugin.java): resolves
	 * the active task from live game state (varps + DBTableID.SlayerTask lookups) rather than
	 * chat text. Task ID 98 is the game's own sentinel for "boss task", requiring a lookup
	 * through SlayerTaskSublist keyed on the separately-tracked boss ID instead.
	 */
	private void updateTaskFromVarps()
	{
		final int bossTaskId = 98;

		int amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (amount <= 0)
		{
			currentTask = null;
			currentTaskAmount = 0;
			currentTaskInitialAmount = 0;
			currentTaskLocation = null;
			taskNpcs.clear();
			superiorNpcs.clear();
			return;
		}

		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int taskDbRow;
		if (taskId == bossTaskId)
		{
			int bossId = client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID);
			List<Integer> bossRows = client.getDBRowsByValue(
				DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
				0,
				bossId);
			if (bossRows.isEmpty())
			{
				log.debug("No SlayerTaskSublist row found for boss ID {}", bossId);
				return;
			}
			taskDbRow = (Integer) client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
		}
		else
		{
			List<Integer> taskRows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
			if (taskRows.isEmpty())
			{
				log.debug("No SlayerTask row found for task ID {}", taskId);
				return;
			}
			taskDbRow = taskRows.get(0);
		}

		String rawTaskName = (String) client.getDBTableField(taskDbRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
		String resolvedCategory = SlayerMonsters.matchCategory(rawTaskName);
		if (resolvedCategory == null)
		{
			log.debug("Unmatched slayer task name from game data: {}", rawTaskName);
			return;
		}

		String location = null;
		int areaId = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		if (areaId > 0)
		{
			List<Integer> areaRows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
			if (!areaRows.isEmpty())
			{
				location = (String) client.getDBTableField(areaRows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)[0];
			}
		}

		boolean taskChanged = !resolvedCategory.equals(currentTask);
		currentTask = resolvedCategory;
		currentTaskAmount = amount;
		currentTaskInitialAmount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		currentTaskLocation = location;

		if (taskChanged)
		{
			assignedByMaster = lastMasterTalkedTo;
			log.debug("Detected slayer task: {}", currentTask);
			rescanTaskNpcs();

			if (config.useShortestPath() && config.autoShortestPath())
			{
				List<SlayerLocations.Location> locations = SlayerLocations.LOCATIONS.get(currentTask);
				if (locations != null && !locations.isEmpty())
				{
					walkToTaskLocation(locations);
				}
			}
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.useShortestPath() || currentTask == null || !"Talk-to".equals(event.getOption()))
		{
			return;
		}

		List<SlayerLocations.Location> locations = SlayerLocations.LOCATIONS.get(currentTask);
		if (locations == null || locations.isEmpty())
		{
			return;
		}

		NPC npc = event.getMenuEntry().getNpc();
		if (npc == null || npc.getName() == null || !SLAYER_MASTERS.contains(npc.getName()))
		{
			return;
		}

		client.getMenu().createMenuEntry(-1)
			.setOption("Walk to task location")
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(e -> walkToTaskLocation(locations));
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!"Talk-to".equals(event.getMenuOption()))
		{
			return;
		}

		NPC npc = event.getMenuEntry().getNpc();
		if (npc != null && npc.getName() != null && SLAYER_MASTERS.contains(npc.getName()))
		{
			lastMasterTalkedTo = npc.getName();
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		List<String> monsters = currentTask == null ? null : SlayerMonsters.TASKS.get(currentTask);
		if (monsters == null)
		{
			return;
		}
		trackIfRelevant(event.getNpc(), monsters);
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		taskNpcs.remove(npc);
		superiorNpcs.remove(npc);
	}

	/**
	 * Rebuilds {@link #taskNpcs}/{@link #superiorNpcs} from scratch against every NPC currently
	 * loaded in the scene. Only run when the task itself changes (rare) -- ongoing tracking is
	 * handled incrementally by {@link #onNpcSpawned}/{@link #onNpcDespawned} so the overlay never
	 * needs to scan the scene on a per-frame basis.
	 */
	private void rescanTaskNpcs()
	{
		taskNpcs.clear();
		superiorNpcs.clear();

		List<String> monsters = SlayerMonsters.TASKS.get(currentTask);
		if (monsters == null)
		{
			return;
		}

		for (NPC npc : client.getTopLevelWorldView().npcs())
		{
			trackIfRelevant(npc, monsters);
		}
	}

	private void trackIfRelevant(NPC npc, List<String> monsters)
	{
		String name = npc.getName();
		if (name == null)
		{
			return;
		}

		if (monsters.contains(name))
		{
			taskNpcs.add(npc);
		}

		for (String monster : monsters)
		{
			if (name.equals(SlayerSuperiors.NORMAL_TO_SUPERIOR.get(monster)))
			{
				taskNpcs.add(npc);
				superiorNpcs.add(npc);
				break;
			}
		}
	}

	private void walkToTaskLocation(List<SlayerLocations.Location> locations)
	{
		WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();
		if (playerLocation == null)
		{
			return;
		}

		SlayerLocations.Location best = pickBestLocation(locations, playerLocation);
		if (best == null)
		{
			return;
		}

		shortestPath.setPath(playerLocation, new WorldPoint(best.x, best.y, best.plane));
	}

	/**
	 * Among the locations the player can currently reach (per {@link SlayerLocations.Location#isSatisfied}),
	 * prefers the one gated by the most requirements -- on the assumption a more restricted spot is likely
	 * a better (safer/higher-yield) variant -- falling back to nearest-by-distance to break ties.
	 */
	private SlayerLocations.Location pickBestLocation(List<SlayerLocations.Location> locations, WorldPoint playerLocation)
	{
		SlayerLocations.Location best = null;
		int bestRequirementCount = -1;
		int bestDistance = Integer.MAX_VALUE;

		for (SlayerLocations.Location location : locations)
		{
			if (!location.isSatisfied(client))
			{
				continue;
			}

			int requirementCount = location.requirementCount();
			int distance = playerLocation.distanceTo(new WorldPoint(location.x, location.y, location.plane));

			if (requirementCount > bestRequirementCount
				|| (requirementCount == bestRequirementCount && distance < bestDistance))
			{
				best = location;
				bestRequirementCount = requirementCount;
				bestDistance = distance;
			}
		}

		return best;
	}

	@Provides
	SlayerAIOConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerAIOConfig.class);
	}
}

package com.slayeraio;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class SlayerTaskOverlay extends OverlayPanel
{
	private static final Color REQUIREMENT_COLOR = Color.YELLOW;
	private static final Color SKIP_COLOR = new Color(255, 80, 80);

	private final SlayerAIOPlugin plugin;
	private final SlayerAIOConfig config;

	// Combat info only changes when the task itself changes, so it's derived once per task and
	// cached here rather than redoing map lookups and style derivation on every render() frame.
	private String cachedTask;
	private SlayerCombatData.Profile cachedProfile;
	private List<SlayerCombatData.MeleeStyle> cachedBestMelee = Collections.emptyList();
	private SlayerCombatData.RangedStyle cachedBestRanged;

	@Inject
	private SlayerTaskOverlay(SlayerAIOPlugin plugin, SlayerAIOConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String task = plugin.getCurrentTask();

		panelComponent.getChildren().clear();
		panelComponent.setWrap(true);
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Slayer Task")
			.color(Color.ORANGE)
			.build());

		if (task == null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Unknown")
				.build());
			return super.render(graphics);
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left(task)
			.build());

		List<String> monsters = SlayerMonsters.TASKS.get(task);
		if (monsters != null && !monsters.isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Counts as:")
				.leftColor(Color.LIGHT_GRAY)
				.build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left(String.join(", ", monsters))
				.build());
		}

		if (config.showCombatInfo())
		{
			addCombatInfo(task, monsters);
		}

		if (config.showTaskEfficiency())
		{
			addEfficiencyInfo(task);
		}

		if (config.showTaskProgress())
		{
			addTaskProgress(task);
		}

		addMasterTips(task);

		return super.render(graphics);
	}

	/**
	 * Community-sourced (not wiki) best-known-method GP/hr and kills/hr for the task, so the
	 * player has concrete numbers to judge whether it's worth doing versus blocking/skipping --
	 * see {@link SlayerTaskEfficiency} for provenance and caveats about the data.
	 */
	private void addEfficiencyInfo(String task)
	{
		SlayerTaskEfficiency.Efficiency eff = SlayerTaskEfficiency.EFFICIENCY.get(task);
		if (eff == null)
		{
			return;
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Best method:")
			.leftColor(Color.LIGHT_GRAY)
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left(eff.variant)
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("GP/hr:")
			.leftColor(Color.LIGHT_GRAY)
			.right(formatNumber(eff.profitPerHour))
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Kills/hr:")
			.leftColor(Color.LIGHT_GRAY)
			.right(formatNumber(eff.killsPerHour))
			.build());

		boolean isXpBasis = config.skipBasis() == SlayerAIOConfig.SkipBasis.XP_PER_HOUR;
		int threshold = isXpBasis ? config.skipBelowXpPerHour() : config.skipBelowGpPerHour();
		double rate = isXpBasis ? eff.xpPerHour : eff.profitPerHour;

		if (threshold > 0 && rate < threshold)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Consider skipping -- low " + (isXpBasis ? "XP/hr" : "GP/hr"))
				.leftColor(SKIP_COLOR)
				.build());
		}

		int remainingKills = plugin.getCurrentTaskAmount();
		if (remainingKills > 0 && eff.killsPerHour > 0)
		{
			double remainingValue = remainingKills * (eff.profitPerHour / eff.killsPerHour);
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Remaining value:")
				.leftColor(Color.LIGHT_GRAY)
				.right("~" + formatNumber(remainingValue) + " gp")
				.build());
		}
	}

	private void addMasterTips(String task)
	{
		String master = plugin.getAssignedByMaster();
		if (master == null)
		{
			return;
		}

		Map<String, SlayerMasterTips.Tip> tipsForMaster = SlayerMasterTips.MASTER_TIPS.get(master);
		if (tipsForMaster == null)
		{
			return;
		}

		SlayerMasterTips.Tip tip = tipsForMaster.get(task);
		if (tip == null)
		{
			return;
		}

		if (tip.bracelet != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Bracelet:")
				.leftColor(Color.LIGHT_GRAY)
				.right(tip.bracelet)
				.build());
		}

		if (tip.extend != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Extend:")
				.leftColor(Color.LIGHT_GRAY)
				.right(tip.extend ? "Yes" : "No")
				.build());
		}
	}

	private void addTaskProgress(String task)
	{
		int initial = plugin.getCurrentTaskInitialAmount();
		int remaining = plugin.getCurrentTaskAmount();
		if (initial <= 0)
		{
			return;
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Progress:")
			.leftColor(Color.LIGHT_GRAY)
			.right((initial - remaining) + "/" + initial + " killed")
			.build());

		SlayerTaskEfficiency.Efficiency eff = SlayerTaskEfficiency.EFFICIENCY.get(task);
		if (eff != null && eff.killsPerHour > 0)
		{
			double etaMinutes = remaining / eff.killsPerHour * 60.0;
			panelComponent.getChildren().add(LineComponent.builder()
				.left("ETA:")
				.leftColor(Color.LIGHT_GRAY)
				.right("~" + Math.round(etaMinutes) + " min")
				.build());
		}
	}

	private static String formatNumber(double value)
	{
		return String.format(Locale.ROOT, "%,.0f", value);
	}

	/**
	 * Combat info is looked up per real monster name (not the task category), since the wiki data
	 * is keyed that way. Uses the first monster in the category with a known profile as
	 * representative -- e.g. "Aberrant spectres" shows Aberrant spectre's data, not Deviant
	 * spectre's, unless only the latter has data.
	 */
	private void addCombatInfo(String task, List<String> monsters)
	{
		if (!Objects.equals(task, cachedTask))
		{
			cachedTask = task;
			cachedProfile = resolveProfile(monsters);
			cachedBestMelee = cachedProfile == null ? Collections.emptyList() : cachedProfile.bestMeleeStyles();
			cachedBestRanged = cachedProfile == null ? null : cachedProfile.bestRangedStyle();
		}

		SlayerCombatData.Profile profile = cachedProfile;
		if (profile == null)
		{
			return;
		}

		if (!cachedBestMelee.isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Best melee:")
				.leftColor(Color.LIGHT_GRAY)
				.right(joinStyles(cachedBestMelee))
				.build());
		}

		if (cachedBestRanged != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Best range/magic:")
				.leftColor(Color.LIGHT_GRAY)
				.right(cachedBestRanged == SlayerCombatData.RangedStyle.MAGE ? "Magic" : "Ranged")
				.build());

			if (cachedBestRanged == SlayerCombatData.RangedStyle.MAGE && profile.elementalWeaknessType != null)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("Weak to:")
					.leftColor(Color.LIGHT_GRAY)
					.right(profile.elementalWeaknessType + " spells +" + profile.elementalWeaknessPercent + "%")
					.build());
			}
		}

		if (Boolean.TRUE.equals(profile.immuneCannon))
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Cannon:")
				.leftColor(REQUIREMENT_COLOR)
				.right("No effect")
				.build());
		}

		if (profile.requirement != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Requires:")
				.leftColor(REQUIREMENT_COLOR)
				.build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left(profile.requirement)
				.leftColor(REQUIREMENT_COLOR)
				.build());
		}

		if (profile.uniqueDropName != null)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Unique drop:")
				.leftColor(Color.LIGHT_GRAY)
				.right(profile.uniqueDropName + " (" + profile.uniqueDropRate + ")")
				.build());
		}
	}

	private static SlayerCombatData.Profile resolveProfile(List<String> monsters)
	{
		if (monsters == null)
		{
			return null;
		}
		for (String monster : monsters)
		{
			SlayerCombatData.Profile profile = SlayerCombatData.MONSTERS.get(monster);
			if (profile != null)
			{
				return profile;
			}
		}
		return null;
	}

	private static String joinStyles(List<SlayerCombatData.MeleeStyle> styles)
	{
		StringBuilder sb = new StringBuilder();
		for (SlayerCombatData.MeleeStyle style : styles)
		{
			if (sb.length() > 0)
			{
				sb.append("/");
			}
			String name = style.name();
			sb.append(name.charAt(0)).append(name.substring(1).toLowerCase(Locale.ROOT));
		}
		return sb.toString();
	}
}

