package com.slayeraio;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/**
 * Soft integration with the "Shortest Path" plugin, using the same handshake Quest Helper uses:
 * a {@link PluginMessage} posted on the shared {@link EventBus}, with no compile-time dependency
 * on shortestpath's own classes. If Shortest Path isn't installed, these calls are harmless no-ops
 * (nothing subscribes to the event).
 */
public class ShortestPathIntegration
{
	private static final String NAMESPACE = "shortestpath";

	@Inject
	private EventBus eventBus;

	public void setPath(WorldPoint start, WorldPoint target)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("start", start);
		data.put("target", target);
		eventBus.post(new PluginMessage(NAMESPACE, "path", data));
	}

	public void clearPath()
	{
		eventBus.post(new PluginMessage(NAMESPACE, "clear"));
	}
}

