/**
 * Outlines NPCs in the scene that count toward the current Slayer task, and separately outlines
 * a spawned superior in its own color. Tracking is spawn/despawn-event-driven (maintained by
 * {@link SlayerAIOPlugin}), not a per-frame scene scan.
 */
class SlayerNpcHighlightOverlay extends Overlay
{
	private final SlayerAIOPlugin plugin;
	private final SlayerAIOConfig config;

	@Inject
	private SlayerNpcHighlightOverlay(SlayerAIOPlugin plugin, SlayerAIOConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.highlightTaskNpcs())
		{
			return null;
		}

		for (NPC npc : plugin.getSuperiorNpcs())
		{
			outline(graphics, npc, config.superiorHighlightColor());
		}

		for (NPC npc : plugin.getTaskNpcs())
		{
			if (plugin.getSuperiorNpcs().contains(npc))
			{
				continue;
			}
			outline(graphics, npc, config.taskNpcHighlightColor());
		}

		return null;
	}

	private static void outline(Graphics2D graphics, NPC npc, Color color)
	{
		Shape hull = npc.getConvexHull();
		if (hull != null)
		{
			OverlayUtil.renderPolygon(graphics, hull, color);
		}
	}
}
